export type Message = keyof typeof messages
export const languages = ['en', 'de', 'ru'] as const
export type Language = typeof languages[number]

function dictionary(index: number): Record<Message, string> {
  return Object.fromEntries(Object.entries(messages).map(([key, row]) => [key, row[index]])) as Record<Message, string>
}

export const dictionaries = { en: dictionary(0), de: dictionary(1), ru: dictionary(2) }
